<dialog class="confirm-dialog" id="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-description">
    <form method="dialog"><h2 id="confirm-title">Smazat záznam?</h2><p id="confirm-description"></p><div class="dialog-actions"><button class="btn btn-outline-secondary" value="cancel" autofocus>Zrušit</button><button class="btn btn-danger" value="confirm">Smazat</button></div></form>
</dialog>
